#!/usr/bin/env bash
# Is the provider string this checkout writes byte-identical to what the real OCM v1 CLI wrote?
#
# The provider is a JSON document embedded in a JSON string, regenerated by
# ConvertToV2Provider on every write, so its bytes land in the stored descriptor.
# encoding/json v1 escaped <, > and & AND U+2028 / U+2029; encoding/json/v2 puts those
# two classes behind separate options (jsontext.EscapeForHTML and jsontext.EscapeForJS).
#
# This builds a component version with the repo-pinned OCM v1 CLI, transfers it with the
# v2 CLI from this checkout, and compares the provider bytes.
#
# Exit codes (review-evidence convention):
#   0  byte-identical to OCM v1  -> correct
#   1  bytes differ              -> reproduced
#   2+ setup failed              -> inconclusive
#
# Needs network on first run to download the pinned OCM v1 CLI (checksum-verified by the
# repository's own installer). Set OCM_V2_BIN to skip building the v2 CLI.

set -uo pipefail

root="$(git rev-parse --show-toplevel)" || exit 2
v1_version="$(sed -n 's/^OCM_V1_VERSION=//p' "$root/conformance/scenarios/compatibility/.env")"
[ -n "$v1_version" ] || { echo "cannot read OCM_V1_VERSION from conformance/scenarios/compatibility/.env" >&2; exit 2; }

bash "$root/conformance/scenarios/compatibility/install.sh" "$v1_version" || exit 2
v1_bin="$root/conformance/scenarios/compatibility/tmp/ocmv1/$v1_version/ocm"
[ -x "$v1_bin" ] || { echo "OCM v1 CLI not executable at $v1_bin" >&2; exit 2; }

v2_bin="${OCM_V2_BIN:-}"
if [ -z "$v2_bin" ]; then
  (cd "$root" && task bindings/go/cli:build >/dev/null) || exit 2
  v2_bin="$root/bindings/go/cli/tmp/bin/ocm"
fi
[ -x "$v2_bin" ] || { echo "OCM v2 CLI not executable at $v2_bin" >&2; exit 2; }

work="$(mktemp -d)" || exit 2
trap 'rm -rf "$work"' EXIT

# An empty OCM config, so neither CLI picks up the developer's own credential sources.
printf 'type: generic.config.ocm.software/v1\nconfigurations: []\n' > "$work/ocmconfig.yaml"

# Provider labels carrying both escape classes. U+2028 is written as the real character.
python3 - "$work" <<'EOF' || exit 2
import pathlib, sys
pathlib.Path(sys.argv[1], "constructor.yaml").write_text(
    "components:\n"
    "- name: ocm.software/review/pr4206\n"
    "  version: 1.0.0\n"
    "  provider:\n"
    "    name: acme\n"
    "    labels:\n"
    "    - name: sep\n"
    '      value: "line1 line2"\n'
    "    - name: html\n"
    '      value: "a<b>c&d"\n'
    "  resources: []\n",
    encoding="utf-8",
)
EOF

"$v1_bin" --config "$work/ocmconfig.yaml" add componentversions \
  --create --file "$work/v1.ctf" --type directory "$work/constructor.yaml" >/dev/null 2>&1 \
  || { echo "OCM v1 could not build the component version" >&2; exit 2; }

"$v2_bin" --config "$work/ocmconfig.yaml" transfer component-version \
  "ctf::$work/v1.ctf//ocm.software/review/pr4206:1.0.0" "ctf::$work/v2.ctf" >/dev/null 2>&1 \
  || { echo "OCM v2 could not transfer the component version" >&2; exit 2; }

python3 - "$work" <<'EOF'
import glob, json, pathlib, re, sys

work = pathlib.Path(sys.argv[1])

# OCM v1 stores the descriptor as YAML inside a tar layer.
v1_yaml = None
for blob in glob.glob(str(work / "v1.ctf" / "blobs" / "*")):
    raw = pathlib.Path(blob).read_bytes()
    if b"component-descriptor.yaml" in raw[:4096] and raw[257:262] == b"ustar":
        import tarfile, io
        with tarfile.open(blob) as tar:
            v1_yaml = tar.extractfile("component-descriptor.yaml").read().decode()
        break
if v1_yaml is None:
    print("could not find the v1 component descriptor", file=sys.stderr)
    sys.exit(2)
match = re.search(r"provider: '(.*)'\n", v1_yaml)
if not match:
    print("could not find the provider in the v1 descriptor", file=sys.stderr)
    sys.exit(2)
v1_provider = match.group(1)

v2_provider = None
for blob in glob.glob(str(work / "v2.ctf" / "blobs" / "*")):
    raw = pathlib.Path(blob).read_bytes()
    if raw.startswith(b'{"component"'):
        v2_provider = json.loads(raw.decode())["component"]["provider"]
        break
if v2_provider is None:
    print("could not find the v2 component descriptor", file=sys.stderr)
    sys.exit(2)

print("OCM v1 wrote     :", v1_provider)
print("this checkout    :", v2_provider)
print()
html_ok = r"\u003c" in v2_provider and r"\u0026" in v2_provider
js_ok = r"\u2028" in v2_provider
print("  <, > and & escaped as v1 did :", html_ok, "(jsontext.EscapeForHTML)")
print("  U+2028 escaped as v1 did     :", js_ok, "(jsontext.EscapeForJS)")
print()

if v1_provider == v2_provider:
    print("RESULT: byte-identical to OCM v1")
    sys.exit(0)

print("RESULT: provider bytes differ from what OCM v1 wrote, so a descriptor written by")
print("        the legacy CLI is not byte-stable through this checkout.")
sys.exit(1)
EOF
